{"additions":32,"deletions":0,"filename":"math-tool.ps1","patch":"@@ -0,0 +1,32 @@
+[CmdletBinding()]
+param(
+    [Parameter(Mandatory)]
+    [ValidateRange(0, [int]::MaxValue)]
+    [int]$N
+)
+
+Set-StrictMode -Version Latest
+
+function Get-Fibonacci {
+    [CmdletBinding()]
+    [OutputType([System.Numerics.BigInteger])]
+    param(
+        [Parameter(Mandatory)]
+        [ValidateRange(0, [int]::MaxValue)]
+        [int]$N
+    )
+
+    $previous = [System.Numerics.BigInteger]::Zero
+    $current = [System.Numerics.BigInteger]::One
+    for ($i = 0; $i -lt $N; $i++) {
+        $next = $previous + $current
+        $previous = $current
+        $current = $next
+    }
+    return $previous
+}
+
+if ($MyInvocation.InvocationName -ne '.') {
+    $result = Get-Fibonacci -N $N
+    Write-Output "Fibonacci($N) = $result"
+}","status":"added"}

